const fs = require('fs');
const html = fs.readFileSync(__dirname + '/index.html', 'utf8');
const js = html.slice(html.indexOf('<script>') + 8, html.lastIndexOf('</script>'));
const phys = js.slice(0, js.indexOf('/* ============================================================\n   Rendering'));
const api = `
function showResult() {}
return {
  run(P, maxT, prof) {
    sim = buildSim(P);
    sim.phase = 'tow'; sim.car.sleeping = false; sim.car.sleepT = 0; sim.car.noSleep = true;
    const W = sim.world, T = {};
    if (prof) for (const k of ['collide', 'updateIslands', 'prepare', 'solveVelocity', 'applyRestitution', 'solvePosition']) {
      const f = W[k].bind(W); T[k] = 0;
      W[k] = (...a) => { const t = performance.now(); const r = f(...a); T[k] += performance.now() - t; return r; };
    }
    const t0 = performance.now();
    let steps = 0, worst = 0, maxAct = 0;
    while (sim.t < maxT && (sim.phase !== 'settled' || !sim.frozen)) {
      const s = performance.now();
      simStep(); steps++;
      if (sim.phase === 'settled' && sim.frozen === undefined) break;
      worst = Math.max(worst, performance.now() - s);
      maxAct = Math.max(maxAct, W.active.length);
    }
    const ms = performance.now() - t0;
    let hash = 0;
    for (const b of sim.bricks) hash += b.x * 1.3 + b.y * 2.7 + b.a * 0.9;
    hash += sim.car.x * 5 + sim.car.y * 7;
    const nan = sim.bricks.filter(b => !Number.isFinite(b.x + b.y + b.a)).length;
    const below = sim.bricks.filter(b => b.minY < -0.03).length;
    return { phase: sim.phase, t: +sim.t.toFixed(3), steps, msPerStep: +(ms / steps).toFixed(3), worstStep: +worst.toFixed(2),
      realtime: +((steps / 240) / (ms / 1000)).toFixed(2), maxAct, hash: hash.toFixed(9), nan, below,
      result: sim.result && { fallen: sim.result.fallen, disp: sim.result.disp, t: +sim.result.t.toFixed(2) },
      awake: sim.bricks.filter(b => !b.sleeping).length,
      prof: prof ? Object.fromEntries(Object.entries(T).map(([k, v]) => [k, +(v / steps).toFixed(3)])) : undefined };
  },
  DEFAULTS,
};`;
const mod = new Function(phys + api)();
const mode = process.argv[2] || 'default';
const D = mod.DEFAULTS;
if (mode === 'default') {
  const a = mod.run({ ...D }, 60, false), b = mod.run({ ...D }, 60, false);
  console.log(a); console.log('determinism', a.hash === b.hash ? 'IDENTICAL' : 'DIFFERENT ' + b.hash);
} else if (mode === 'prof') {
  console.log('default', mod.run({ ...D }, 60, true));
  console.log('big', mod.run({ ...D, cols: 24, rows: 16, layers: 5 }, 12, true));
} else if (mode === 'sweep') {
  const cases = [
    { carSpeed: 5, brickMass: 12 }, { carSpeed: 10 }, { brickMass: 0.5 }, { carSpeed: 45 },
    { carSpeed: 45, brickMass: 0.5, rows: 16, cols: 4, layers: 1 }, { brickMass: 12, rows: 3, cols: 24, layers: 5 },
    { carSpeed: 5, brickMass: 0.5, rows: 16, cols: 24, layers: 1 }, { carMass: 4000, carSpeed: 45, rows: 16 },
    { carMass: 500, brickMass: 12, rows: 16, layers: 5, carSpeed: 30 }, { gravity: 25, brickRestitution: 0.8, brickFriction: 0.05 },
    { gravity: 1, groundFriction: 0.1, brickFriction: 1.2 },
  ];
  for (const c of cases) { const r = mod.run({ ...D, ...c }, 150, false); delete r.prof; console.log(JSON.stringify(c), JSON.stringify(r)); }
}

