  const phys = js.slice(0, js.indexOf('/* ============================================================\n   Rendering'));
  return new Function(phys + `
function showResult() {}
return { run(P, maxT) {
  sim = buildSim(P); sim.phase = 'tow'; sim.car.sleeping = false; sim.car.sleepT = 0; sim.car.noSleep = true;
  const t0 = performance.now(); let n = 0;
  while (sim.t < maxT) { simStep(); n++; }
  return (performance.now() - t0) / n;
}, DEFAULTS };`)();
}
const A = load('_old.html'), B = load('index.html');
const P = { ...A.DEFAULTS, cols: 24, rows: 16, layers: 3 };
const ra = [], rb = [];
for (let i = 0; i < 4; i++) { ra.push(A.run(P, 2.5)); rb.push(B.run(P, 2.5)); }
const med = a => a.slice().sort((x, y) => x - y)[a.length >> 1];
console.log('old ms/step', ra.map(x => x.toFixed(2)).join(' '), 'median', med(ra).toFixed(2));
console.log('new ms/step', rb.map(x => x.toFixed(2)).join(' '), 'median', med(rb).toFixed(2));
EOF
