const { spawn } = require('child_process');
const fs = require('fs');
const path = require('path');

const dir = __dirname;
const shots = path.join(dir, '_shots2');
fs.mkdirSync(shots, { recursive: true });
const W = +(process.argv[2] || 1280), H = +(process.argv[3] || 720), mode = process.argv[4] || 'run';
const port = 9340 + (W % 50);
const chrome = spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', [
  '--headless=new', `--remote-debugging-port=${port}`, `--user-data-dir=${path.join(dir, '_chrome2')}`,
  `--window-size=${W},${H}`, '--no-first-run', '--no-default-browser-check', '--hide-scrollbars',
  '--disable-background-timer-throttling', '--disable-renderer-backgrounding', 'about:blank',
], { stdio: 'ignore' });

const sleep = ms => new Promise(r => setTimeout(r, ms));
let ws, seq = 0;
const pending = new Map();
const logs = [];
function send(method, params = {}) {
  const id = ++seq;
  ws.send(JSON.stringify({ id, method, params }));
  return new Promise((res, rej) => pending.set(id, { res, rej }));
}
async function ev(expr) {
  const r = await send('Runtime.evaluate', { expression: expr, returnByValue: true, awaitPromise: true });
  if (r.exceptionDetails) throw new Error(JSON.stringify(r.exceptionDetails).slice(0, 400));
  return r.result.value;
}
async function shot(name) {
  const r = await send('Page.captureScreenshot', { format: 'png' });
  fs.writeFileSync(path.join(shots, name + '.png'), Buffer.from(r.data, 'base64'));
}
async function waitFor(expr, ms) {
  const t0 = Date.now();
  while (Date.now() - t0 < ms) { if (await ev(expr)) return true; await sleep(100); }
  return false;
}
const HASH = `(() => { let h = 0; for (const b of sim.bricks) h += b.x * 1.3 + b.y * 2.7 + b.a * 0.9; h += sim.car.x * 5 + sim.car.y * 7; return h.toFixed(9); })()`;
const STATE = `({ phase: sim.phase, frozen: sim.frozen, t: +sim.t.toFixed(3), S: +view.S.toFixed(1), rate: document.getElementById('t-rate').textContent,
  disp: document.getElementById('t-disp-pct').textContent, mini: getComputedStyle(document.getElementById('params-mini')).display,
  params: getComputedStyle(document.getElementById('params')).display, zoom: document.getElementById('zoom-lbl').textContent,
  result: document.getElementById('result').hidden ? null : document.getElementById('result').innerText.replace(/\\n+/g, ' | ') })`;

(async () => {
  let wsUrl;
  for (let i = 0; i < 60 && !wsUrl; i++) {
    try {
      const list = await (await fetch(`http://127.0.0.1:${port}/json`)).json();
      wsUrl = list.find(t => t.type === 'page').webSocketDebuggerUrl;
    } catch { await sleep(150); }
  }
  ws = new WebSocket(wsUrl);
  await new Promise(r => ws.addEventListener('open', r));
  ws.addEventListener('message', e => {
    const m = JSON.parse(e.data);
    if (m.id && pending.has(m.id)) { const p = pending.get(m.id); pending.delete(m.id); m.error ? p.rej(new Error(m.error.message)) : p.res(m.result); }
    if (m.method === 'Runtime.consoleAPICalled' && (m.params.type === 'error' || m.params.type === 'warning')) logs.push(m.params.args.map(a => a.value ?? a.description).join(' '));
    if (m.method === 'Runtime.exceptionThrown') logs.push('EXC ' + JSON.stringify(m.params.exceptionDetails).slice(0, 300));
  });
  await send('Runtime.enable');
  await send('Page.enable');
  await send('Emulation.setDeviceMetricsOverride', { width: W, height: H, deviceScaleFactor: 1, mobile: false });
  await send('Page.navigate', { url: 'file://' + path.join(dir, 'index.html') });
  await sleep(1200);
  console.log('title', JSON.stringify(await ev(`[document.title, document.querySelector('h1').textContent]`)));

  if (mode === 'run') {
    console.log('initial', JSON.stringify(await ev(STATE)));
    await shot(`${W}_a_initial`);
    await ev(`document.getElementById('btn-test').click()`);
    await sleep(1150);
    await shot(`${W}_b_crash`);
    await waitFor(`sim.phase === 'settled'`, 30000);
    console.log('verdict', JSON.stringify(await ev(STATE)));
    await waitFor(`sim.frozen`, 60000);
    await sleep(300);
    console.log('frozen', JSON.stringify(await ev(STATE)));
    console.log('browser hash', await ev(HASH));
    await shot(`${W}_c_frozen`);
  } else if (mode === 'zoom') {
    await ev(`window.dispatchEvent(new KeyboardEvent('keydown', { key: 'z', code: 'KeyZ' }))`);
    await sleep(1500);
    console.log('zoom ready', JSON.stringify(await ev(STATE)));
    await shot(`${W}_z_ready`);
    await ev(`document.getElementById('btn-test').click()`);
    await sleep(900);
    await shot(`${W}_z_impact`);
    await sleep(2500);
    await shot(`${W}_z_debris`);
    await ev(`document.getElementById('btn-zoom').click()`);
    await sleep(1500);
    console.log('zoom back', JSON.stringify(await ev(STATE)));
    await shot(`${W}_z_fit`);
  } else if (mode === 'ui') {
    const setN = (k, v) => ev(`(() => { const n = document.getElementById('in-${k}-n'); n.value = ${JSON.stringify(v)}; n.dispatchEvent(new Event('change')); })()`);
    const key = (k, code) => ev(`window.dispatchEvent(new KeyboardEvent('keydown', { key: ${JSON.stringify(k)}, code: ${JSON.stringify(code)}, bubbles: true }))`);
    const UI = `({ phase: sim.phase, bricks: sim.bricks.length, applied: [applied.cols, applied.rows, applied.layers, applied.brickMass, applied.carSpeed],
      settings: [settings.cols, settings.rows, settings.layers, settings.brickMass, settings.carSpeed], pendingHidden: document.getElementById('pending').hidden,
      next: (document.querySelector('#params .pend') || {}).textContent || '', mini: document.getElementById('params-mini').innerText.replace(/\\n/g, ' | '),
      panelClosed: document.getElementById('settings').classList.contains('closed'), zoom: document.getElementById('zoom-lbl').textContent })`;
    await setN('cols', 18); await setN('rows', 12); await setN('layers', 3); await setN('brickMass', 99);
    await sleep(500);
    console.log('idle edits', JSON.stringify(await ev(UI)));
    await ev(`document.getElementById('btn-defaults').click()`);
    await sleep(500);
    console.log('defaults', JSON.stringify(await ev(UI)));
    await setN('carSpeed', 6); await setN('brickMass', 12);
    await sleep(400);
    await ev(`document.activeElement && document.activeElement.blur()`);
    await key(' ', 'Space');
    await sleep(200);
    await setN('cols', 6);
    console.log('edit during run', JSON.stringify(await ev(UI)));
    await waitFor(`sim.frozen`, 30000);
    console.log('slow heavy', JSON.stringify(await ev(`({ phase: sim.phase, frozen: sim.frozen, result: document.getElementById('result').innerText.replace(/\\n+/g, ' | ') })`)));
    await shot(`${W}_ui_slow_heavy`);
    await key('r', 'KeyR');
    await sleep(300);
    console.log('after R', JSON.stringify(await ev(UI)));
    await key('s', 'KeyS'); await sleep(350);
    const s1 = await ev(UI);
    await key('s', 'KeyS'); await key('z', 'KeyZ'); await sleep(350);
    const s2 = await ev(UI);
    await key('z', 'KeyZ'); await sleep(200);
    console.log('S/Z keys', JSON.stringify({ afterS: s1.panelClosed, afterSS: s2.panelClosed, zoomAfterZ: s2.zoom, zoomAfterZZ: (await ev(UI)).zoom }));
  } else if (mode === 'big') {
    await ev(`(() => { for (const [k, v] of [['cols', 24], ['rows', 16], ['layers', 5]]) { const n = document.getElementById('in-' + k + '-n'); n.value = v; n.dispatchEvent(new Event('change')); } })()`);
    await sleep(900);
    console.log('big ready', JSON.stringify(await ev(`({ bricks: sim.bricks.length })`)));
    await ev(`document.getElementById('btn-test').click()`);
    await waitFor(`sim.phase === 'crash'`, 10000);
    await ev(`window.__f = 0; window.__t0 = performance.now(); window.__s0 = sim.t; (function c() { window.__f++; if (performance.now() - window.__t0 < 3000) requestAnimationFrame(c); })()`);
    await sleep(3200);
    console.log('big perf', JSON.stringify(await ev(`({ fps: +(window.__f / 3).toFixed(1), simRate: +((sim.t - window.__s0) / ((performance.now() - window.__t0) / 1000)).toFixed(2), rate: document.getElementById('t-rate').textContent, phase: sim.phase })`)));
    await shot(`${W}_big`);
  }
  console.log('console:', logs.length ? logs.join('\n') : '(clean)');
  ws.close();
  chrome.kill();
  process.exit(0);
})().catch(e => { console.error('FAIL', e.message); chrome.kill(); process.exit(1); });

